BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;
SET LOCAL search_path=extensions,pg_catalog,public;
SELECT plan(34);
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conname='db03_handoff_initial_enrollment_source_key' AND conrelid='app_private.enrollments'::regclass AND contype='u' AND cardinality(conkey)=5),'enrollment original Student Section and kind composite key');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conname='db03_handoff_initial_roll_source_key' AND conrelid='app_private.roll_allocations'::regclass AND contype='u' AND cardinality(conkey)=3),'roll original allocation enrollment and Student key');
SELECT ok((SELECT count(*)=4 FROM pg_attribute WHERE attrelid='app_private.admission_student_handoffs'::regclass AND attname IN('result_enrollment_id','result_roll_allocation_id','required_placement_kind','required_entry_kind') AND NOT attisdropped),'four handoff lineage columns installed');
SELECT ok((SELECT count(*)=2 FROM pg_attribute WHERE attrelid='app_private.admission_student_handoffs'::regclass AND attname IN('result_enrollment_id','result_roll_allocation_id') AND NOT attnotnull AND NOT attisdropped),'READY permits missing resulting placement and roll');
SELECT ok((SELECT count(*)=2 FROM pg_attribute WHERE attrelid='app_private.admission_student_handoffs'::regclass AND attname IN('required_placement_kind','required_entry_kind') AND attnotnull AND NOT attisdropped),'placement kind and entry kind mandatory');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conname='db03_handoff_initial_placement_kind_check' AND contype='c'),'only primary placement kind allowed');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conname='db03_handoff_initial_entry_kind_check' AND contype='c'),'only initial entry kind allowed');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conname='db03_handoff_initial_placement_state_check' AND contype='c'),'READY and CONSUMED placement/roll shape enforced');
SELECT ok((SELECT pg_get_constraintdef(oid) LIKE '%result_enrollment_id IS NULL%' FROM pg_constraint WHERE conname='db03_handoff_initial_placement_state_check'),'READY demands no enrollment ID');
SELECT ok((SELECT pg_get_constraintdef(oid) LIKE '%result_roll_allocation_id IS NULL%' FROM pg_constraint WHERE conname='db03_handoff_initial_placement_state_check'),'READY demands no roll ID');
SELECT ok((SELECT pg_get_constraintdef(oid) LIKE '%result_enrollment_id IS NOT NULL%' FROM pg_constraint WHERE conname='db03_handoff_initial_placement_state_check'),'CONSUMED demands initial enrollment ID');
SELECT ok((SELECT pg_get_constraintdef(oid) LIKE '%result_roll_allocation_id IS NOT NULL%' FROM pg_constraint WHERE conname='db03_handoff_initial_placement_state_check'),'CONSUMED demands roll allocation ID');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conname='db03_handoff_result_enrollment_one_link' AND contype='u'),'initial enrollment cannot serve two handoffs');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conname='db03_handoff_result_roll_one_link' AND contype='u'),'initial roll cannot serve two handoffs');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conname='db03_handoff_exact_initial_primary_enrollment' AND contype='f' AND conrelid='app_private.admission_student_handoffs'::regclass AND confrelid='app_private.enrollments'::regclass AND cardinality(conkey)=5),'exact original INITIAL PRIMARY Enrollment FK');
SELECT ok((SELECT pg_get_constraintdef(oid) LIKE '%result_enrollment_id, result_student_id, section_offering_id, required_placement_kind, required_entry_kind%' FROM pg_constraint WHERE conname='db03_handoff_exact_initial_primary_enrollment'),'result enrollment has exact Student Section and kinds');
SELECT ok((SELECT pg_get_constraintdef(oid) LIKE '%id, student_id, section_offering_id, placement_kind, entry_kind%' FROM pg_constraint WHERE conname='db03_handoff_exact_initial_primary_enrollment'),'D1 source fields enforce immutable original placement');
SELECT ok((SELECT condeferrable AND condeferred FROM pg_constraint WHERE conname='db03_handoff_exact_initial_primary_enrollment'),'initial enrollment FK checked at COMMIT');
SELECT ok((SELECT confupdtype='a' AND confdeltype='a' FROM pg_constraint WHERE conname='db03_handoff_exact_initial_primary_enrollment'),'deferred FK uses NO ACTION integrity');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conname='db03_handoff_exact_initial_roll' AND contype='f' AND conrelid='app_private.admission_student_handoffs'::regclass AND confrelid='app_private.roll_allocations'::regclass AND cardinality(conkey)=3),'exact initial roll allocation FK');
SELECT ok((SELECT pg_get_constraintdef(oid) LIKE '%result_roll_allocation_id, result_enrollment_id, result_student_id%' FROM pg_constraint WHERE conname='db03_handoff_exact_initial_roll'),'roll references exact handoff Enrollment and Student');
SELECT ok((SELECT pg_get_constraintdef(oid) LIKE '%id, enrollment_id, student_id%' FROM pg_constraint WHERE conname='db03_handoff_exact_initial_roll'),'roll origin identity source fields match');
SELECT ok((SELECT condeferrable AND condeferred FROM pg_constraint WHERE conname='db03_handoff_exact_initial_roll'),'roll FK checked at COMMIT');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conname='db03_principal_approval_requires_consumed_handoff' AND condeferrable AND condeferred),'P50 approved requires CONSUMED handoff');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conname='db03_handoff_exact_principal_approval' AND condeferrable AND condeferred),'P50 handoff reciprocal Principal approval');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conname='db03_handoff_exact_d1_student_number_person' AND condeferrable AND condeferred),'P53 correct Student Person number enforced');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conname='db03_handoff_section_same_class'),'P40 approved Section Class preserved');
SELECT ok((SELECT count(*)=3 FROM pg_class WHERE oid IN('app_private.enrollments'::regclass,'app_private.roll_allocations'::regclass,'app_private.admission_student_handoffs'::regclass) AND relrowsecurity AND relforcerowsecurity),'Enrollment Roll Handoff retain forced RLS');
SELECT ok((SELECT count(*)=1 FROM pg_trigger WHERE tgname='db03_handoff_mutation_disabled' AND tgenabled='O' AND NOT tgisinternal),'deny-all handoff writer retained');
SELECT ok(NOT has_table_privilege('authenticated','app_private.admission_student_handoffs','INSERT'),'no client handoff writer grant');
SELECT ok(NOT has_table_privilege('schoolos_workflow_executor','app_private.admission_student_handoffs','INSERT'),'no workflow handoff writer grant');
SELECT ok(to_regprocedure('app.approve_admission_principal(uuid,bigint,uuid,uuid)') IS NULL,'no activated Principal approval');
SELECT ok((SELECT count(*)=0 FROM app_private.operation_contracts WHERE code='student.create' AND enabled),'student.create still disabled');
SELECT ok((SELECT count(*)=0 FROM app_private.admission_student_handoffs),'no fake handoffs created');
SELECT * FROM finish();
ROLLBACK;
